"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["35270"],{38979(a){a.exports=JSON.parse('{"id":"F340","slug":"swap-fixed-rate","name":"Interest Rate Swap: Fair Fixed Rate","subject":"Derivatives","section":"Derivatives","topic":"Interest rate swaps","level":"Intermediate","aliases":["swap rate","par swap rate","plain vanilla swap","pay fixed receive floating"],"formula":{"latex":"c=\\\\frac{1-DF_{n}}{\\\\sum_{i=1}^{n}DF_{i}}","also":[],"text":"Fair fixed rate = (1 - Discount factor for the last payment date) / Sum of all the discount factors"},"symbols":[{"symbol":"DF_i","meaning":"Discount factor for payment date i, the value today of 1 received on that date","unit":"number"},{"symbol":"c","meaning":"Fixed rate that gives the swap zero value at the start","unit":"per year"},{"symbol":"Notional","meaning":"Amount on which payments are calculated. It is never exchanged","unit":"money"}],"when_to_use":"Use it to find the fixed rate at which a swap costs nothing to enter. In a plain vanilla swap one side pays a fixed rate and the other pays a floating rate such as SOFR on the same notional. Only the net difference is paid on each date.","worked_example":{"problem":"Annual discount factors for years 1 to 4 are 0.9615, 0.9246, 0.8890 and 0.8548. What is the fair fixed rate on a 4-year annual swap with a notional of 10,000,000? If the floating rate for the first year turns out to be 4.5%, what is the first net payment?","inputs":{"df":[0.9615,0.9246,0.889,0.8548],"notional":10000000,"float":4.5},"steps":[{"label":"Sum of discount factors","working":null,"value":"3.6299"},{"label":"Fixed rate = (1 - last discount factor) / sum","working":null,"value":"4.000%"},{"label":"First net payment to the fixed payer = notional x (floating - fixed)","working":"10,000,000 x (0.045-0.0400011)","value":"49,988.98"}],"answer":"The fair fixed rate is 4.000%. Against a first-year floating rate of 4.5% the fixed payer receives a net 49,988.98 (floating received less fixed paid). If the net were negative, the fixed payer would owe it."},"calculator":{"available":true,"inputs":[{"id":"df","label":"Discount factors for each payment date","unit":"","type":"list","default":[0.9615,0.9246,0.889,0.8548],"hint":""},{"id":"notional","label":"Notional","unit":"money","type":"number","default":10000000,"hint":""},{"id":"float","label":"First-year floating rate","unit":"%","type":"number","default":4.5,"hint":""}],"checks":[{"expr":"count(df)>=1","message":"Enter at least one discount factor."}],"steps":[{"id":"ann","label":"Sum of discount factors","expr":"sum(df)","format":"num4"},{"id":"c","label":"Fixed rate = (1 - last discount factor) / sum","expr":"(1-last(df, 1)[0])/ann","format":"pct3"},{"id":"net","label":"First net payment to the fixed payer = notional x (floating - fixed)","expr":"notional*(float-c)","format":"money"}],"results":["c","net"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"ann":3.6299,"c":0.04000110195873164,"net":49988.98041268358}},"finder":{"finds":"The fixed rate that makes a swap worth zero","needs":"Discount factors, notional, floating rate"},"related":[{"slug":"swap-value","name":"Interest Rate Swap: Value After Inception"},{"slug":"bootstrap-spot-rates","name":"Bootstrapping Spot Rates from Par Yields"},{"slug":"swap-comparative-advantage","name":"Swap Gains from Comparative Advantage"}],"related_ids":["F341","F293","F342"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mn>1</mn><mo>\u2212</mo><mi>D</mi><msub><mi>F</mi><mi>n</mi></msub></mrow><mrow><munderover><mo>\u2211</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mi>D</mi><msub><mi>F</mi><mi>i</mi></msub></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">c=\\\\frac{1-DF_{n}}{\\\\sum_{i=1}^{n}DF_{i}}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>c</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle c</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mfrac><mrow><mn>1</mn><mo>\u2212</mo><mi>D</mi><msub><mi>F</mi><mi>n</mi></msub></mrow><mrow><munderover><mo>\u2211</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mi>D</mi><msub><mi>F</mi><mi>i</mi></msub></mrow></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\frac{1-DF_{n}}{\\\\sum_{i=1}^{n}DF_{i}}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"cap-floor-payoffs","name":"Interest Rate Cap and Floor Payoffs"},"next":{"slug":"swap-value","name":"Interest Rate Swap: Value After Inception"},"lesson":null,"total":522}')}}]);